   337→/// Parse Stream Deck button report
   338→///
   339→/// Stream Deck reports button states as a byte array where each byte
   340→/// represents a button (1 = pressed, 0 = not pressed).
   341→///
   342→/// Report format varies by model:
   343→/// - Original/Mini: [report_id, button0, button1, ..., buttonN]
   344→/// - MK.2/XL: [report_id, extra1, extra2, extra3, button0, button1, ...]
   345→fn parse_streamdeck_report(
   346→    device_id: &Uuid,
   347→    report: &[u8],
   348→    device_info: &mut OpenDeviceInfo,
   349→    timestamp: Instant,
   350→) -> Vec<RawButtonEvent> {
   351→    let mut events = Vec::new();
   352→
   353→    // Verify minimum report size
   354→    if report.is_empty() {
   355→        return events;
   356→    }
   357→
   358→    // Determine button data offset based on model
   359→    let button_data_offset = match device_info.stream_deck_model {
   360→        Some(StreamDeckModel::Mk2) | Some(StreamDeckModel::Xl) => {
   361→            // New format: [report_id, 0x00, extra, extra, button_states...]
   362→            4
   363→        }
   364→        _ => {
   365→            // Standard format: [report_id, button_states...]
   366→            1
   367→        }
   368→    };
   369→
   370→    // Ensure report has enough data
   371→    if report.len() <= button_data_offset {
   372→        return events;
   373→    }
   374→
   375→    let button_data = &report[button_data_offset..];
   376→
   377→    for (index, &button_byte) in button_data.iter().enumerate() {
   378→        if index >= device_info.button_count as usize {
   379→            break;
   380→        }
   381→
   382→        let is_pressed = button_byte != 0;
   383→        let was_pressed = device_info
   384→            .previous_states
   385→            .get(index)
   386→            .copied()
   387→            .unwrap_or(false);
   388→
   389→        // Generate event on state change
   390→        if is_pressed != was_pressed {
   391→            events.push(RawButtonEvent {
   392→                device_id: *device_id,
   393→                button_code: index as u8,
   394→                pressed: is_pressed,
   395→                timestamp,
   396→            });
   397→
   398→            let model_name = device_info
   399→                .stream_deck_model
   400→                .map(|m| m.name())
   401→                .unwrap_or("Stream Deck");
   402→
   403→            tracing::debug!(
   404→                "{} button {} {}",
   405→                model_name,
   406→                index,
   407→                if is_pressed { "pressed" } else { "released" }
   408→            );
   409→        }
   410→
   411→        // Update state
   412→        if index < device_info.previous_states.len() {
   413→            device_info.previous_states[index] = is_pressed;
   414→        }
   415→    }
   416→
   417→    events
   418→}
