    12→/// A button mapping configuration
    13→#[derive(Debug, Clone)]
    14→pub struct ButtonMapping {
    15→    /// Unique ID for this mapping
    16→    pub id: Uuid,
    17→    /// Device this mapping belongs to
    18→    pub device_id: Uuid,
    19→    /// Button code from the device
    20→    pub button_code: u8,
    21→    /// Action to execute
    22→    pub action: ButtonAction,
    23→    /// Optional label for the button
    24→    pub label: Option<String>,
    25→    /// Whether this mapping is enabled
    26→    pub enabled: bool,
    27→}
    28→
    29→impl ButtonMapping {
    30→    /// Create a new button mapping
    31→    pub fn new(device_id: Uuid, button_code: u8, action: ButtonAction) -> Self {
    32→        Self {
    33→            id: Uuid::new_v4(),
    34→            device_id,
    35→            button_code,
    36→            action,
    37→            label: None,
    38→            enabled: true,
    39→        }
    40→    }
    41→
    42→    /// Set the label
    43→    pub fn with_label(mut self, label: impl Into<String>) -> Self {
    44→        self.label = Some(label.into());
    45→        self
    46→    }
    47→}
    48→
    49→/// Raw button event from device
    50→#[derive(Debug, Clone)]
    51→pub struct RawButtonEvent {
    52→    /// Device ID
    53→    pub device_id: Uuid,
    54→    /// Button code
    55→    pub button_code: u8,
    56→    /// Whether button is pressed (true) or released (false)
    57→    pub pressed: bool,
    58→    /// When the event occurred
    59→    pub timestamp: Instant,
    60→}
    61→
    62→/// Button action event (after mapping)
    63→#[derive(Debug, Clone)]
    64→pub struct ButtonActionEvent {
    65→    /// Device ID
    66→    pub device_id: Uuid,
    67→    /// Mapping ID
    68→    pub mapping_id: Uuid,
    69→    /// The action to execute
    70→    pub action: ButtonAction,
    71→    /// When the event occurred
    72→    pub timestamp: Instant,
    73→}
    74→
    75→/// Trait for button input handling
    76→pub trait ButtonInputHandler: Send + Sync {
    77→    /// Register button mappings for a device
    78→    fn register_mappings(&self, device_id: &Uuid, mappings: Vec<ButtonMapping>);
    79→
    80→    /// Get mappings for a device
    81→    fn get_mappings(&self, device_id: &Uuid) -> Vec<ButtonMapping>;
    82→
    83→    /// Add a single mapping
    84→    fn add_mapping(&self, device_id: &Uuid, mapping: ButtonMapping);
    85→
    86→    /// Remove a mapping
    87→    fn remove_mapping(&self, mapping_id: &Uuid);
    88→
    89→    /// Update a mapping's action
    90→    fn update_mapping(&self, mapping_id: &Uuid, new_action: ButtonAction);
    91→
    92→    /// Clear all mappings for a device
    93→    fn clear_mappings(&self, device_id: &Uuid);
    94→
    95→    /// Subscribe to button press events (after mapping)
    96→    fn subscribe_actions(&self) -> broadcast::Receiver<ButtonActionEvent>;
    97→
    98→    /// Subscribe to raw button events (for mapping UI)
    99→    fn subscribe_raw(&self) -> broadcast::Receiver<RawButtonEvent>;
   100→
   101→    /// Start learning mode (for mapping new buttons)
   102→    fn start_learning_mode(&self, device_id: &Uuid);
   103→
   104→    /// Stop learning mode
   105→    fn stop_learning_mode(&self);
   106→
   107→    /// Check if in learning mode
   108→    fn is_learning(&self) -> bool;
   109→
   110→    /// Get the last learned button code
   111→    fn get_learned_button(&self) -> Option<u8>;
   112→}
   113→
   114→/// Default button input handler implementation
   115→pub struct DefaultButtonInputHandler {
   116→    mappings: Arc<RwLock<HashMap<Uuid, Vec<ButtonMapping>>>>,
   117→    action_tx: broadcast::Sender<ButtonActionEvent>,
   118→    raw_tx: broadcast::Sender<RawButtonEvent>,
   119→    learning_mode: Arc<RwLock<Option<Uuid>>>,
   120→    learned_button: Arc<RwLock<Option<u8>>>,
   121→}
   122→
   123→impl Default for DefaultButtonInputHandler {
   124→    fn default() -> Self {
   125→        Self::new()
   126→    }
   127→}
   128→
   129→impl DefaultButtonInputHandler {
   130→    /// Create a new button input handler
   131→    pub fn new() -> Self {
   132→        let (action_tx, _) = broadcast::channel(100);
   133→        let (raw_tx, _) = broadcast::channel(100);
   134→
   135→        Self {
   136→            mappings: Arc::new(RwLock::new(HashMap::new())),
   137→            action_tx,
   138→            raw_tx,
   139→            learning_mode: Arc::new(RwLock::new(None)),
   140→            learned_button: Arc::new(RwLock::new(None)),
   141→        }
   142→    }
   143→
   144→    /// Process a raw button event
   145→    pub async fn process_event(&self, event: RawButtonEvent) {
   146→        // Send raw event
   147→        let _ = self.raw_tx.send(event.clone());
   148→
   149→        // Check if in learning mode
   150→        if let Some(_learning_device) = self.learning_mode.read().await.as_ref() {
   151→            if event.pressed {
   152→                *self.learned_button.write().await = Some(event.button_code);
   153→            }
   154→            return;
   155→        }
   156→
   157→        // Only process button presses, not releases
   158→        if !event.pressed {
   159→            return;
   160→        }
   161→
   162→        // Look up mapping
   163→        let mappings = self.mappings.read().await;
   164→        if let Some(device_mappings) = mappings.get(&event.device_id) {
   165→            if let Some(mapping) = device_mappings
   166→                .iter()
   167→                .find(|m| m.button_code == event.button_code && m.enabled)
   168→            {
   169→                let action_event = ButtonActionEvent {
   170→                    device_id: event.device_id,
   171→                    mapping_id: mapping.id,
   172→                    action: mapping.action.clone(),
   173→                    timestamp: event.timestamp,
   174→                };
   175→
   176→                let _ = self.action_tx.send(action_event);
   177→            }
   178→        }
   179→    }
   180→}
   181→
   182→impl ButtonInputHandler for DefaultButtonInputHandler {
   183→    fn register_mappings(&self, device_id: &Uuid, mappings: Vec<ButtonMapping>) {
   184→        if let Ok(mut m) = self.mappings.try_write() {
   185→            m.insert(*device_id, mappings);
   186→        }
   187→    }
   188→
   189→    fn get_mappings(&self, device_id: &Uuid) -> Vec<ButtonMapping> {
   190→        self.mappings
   191→            .try_read()
   192→            .ok()
   193→            .and_then(|m| m.get(device_id).cloned())
   194→            .unwrap_or_default()
   195→    }
   196→
   197→    fn add_mapping(&self, device_id: &Uuid, mapping: ButtonMapping) {
   198→        if let Ok(mut mappings) = self.mappings.try_write() {
   199→            mappings.entry(*device_id).or_default().push(mapping);
   200→        }
   201→    }
   202→
   203→    fn remove_mapping(&self, mapping_id: &Uuid) {
   204→        if let Ok(mut mappings) = self.mappings.try_write() {
   205→            for device_mappings in mappings.values_mut() {
   206→                device_mappings.retain(|m| &m.id != mapping_id);
   207→            }
   208→        }
   209→    }
   210→
   211→    fn update_mapping(&self, mapping_id: &Uuid, new_action: ButtonAction) {
   212→        if let Ok(mut mappings) = self.mappings.try_write() {
   213→            for device_mappings in mappings.values_mut() {
   214→                if let Some(mapping) = device_mappings.iter_mut().find(|m| &m.id == mapping_id) {
   215→                    mapping.action = new_action;
   216→                    break;
   217→                }
   218→            }
   219→        }
   220→    }
   221→
   222→    fn clear_mappings(&self, device_id: &Uuid) {
   223→        if let Ok(mut mappings) = self.mappings.try_write() {
   224→            mappings.remove(device_id);
   225→        }
   226→    }
   227→
   228→    fn subscribe_actions(&self) -> broadcast::Receiver<ButtonActionEvent> {
   229→        self.action_tx.subscribe()
   230→    }
   231→
   232→    fn subscribe_raw(&self) -> broadcast::Receiver<RawButtonEvent> {
   233→        self.raw_tx.subscribe()
   234→    }
   235→
   236→    fn start_learning_mode(&self, device_id: &Uuid) {
   237→        if let Ok(mut learning) = self.learning_mode.try_write() {
   238→            *learning = Some(*device_id);
   239→        }
   240→        if let Ok(mut learned) = self.learned_button.try_write() {
   241→            *learned = None;
   242→        }
   243→
   244→        tracing::info!("Started button learning mode for device {:?}", device_id);
   245→    }
   246→
   247→    fn stop_learning_mode(&self) {
   248→        if let Ok(mut learning) = self.learning_mode.try_write() {
   249→            *learning = None;
   250→        }
   251→
   252→        tracing::info!("Stopped button learning mode");
