     1→//! Audio Engine
     2→//!
     3→//! Core audio playback engine using rodio.
     4→//!
     5→//! # Priority-Based Interruption
     6→//!
     7→//! The audio engine implements a priority queue system where higher-priority
     8→//! items (like interval changes) can interrupt lower-priority items currently
     9→//! playing. Priority levels are:
    10→//!
    11→//! - `Critical` - Interrupts everything immediately
    12→//! - `High` - Interrupts Normal and Low priority items
    13→//! - `Normal` - Standard priority, queued normally
    14→//! - `Low` - Can be skipped if queue is full
    15→
    16→use super::tts::TtsProvider;
    17→use super::{
    18→    AudioConfig, AudioError, AudioEvent, AudioItem, AudioPriority, AudioType,
    19→    ThreadSafeTtsProvider,
    20→};
    21→use std::collections::BinaryHeap;
    22→use std::sync::atomic::{AtomicBool, Ordering};
    23→use std::sync::{Arc, Mutex};
    24→use std::time::Duration;
    25→use tokio::sync::broadcast;
    26→
    27→/// Trait for audio engine implementations
    28→pub trait AudioEngine: Send + Sync {
    29→    /// Initialize the audio engine
    30→    fn initialize(&self) -> Result<(), AudioError>;
    31→
    32→    /// Play a sound effect by name
    33→    fn play_sound(
    34→        &self,
    35→        name: &str,
    36→    ) -> impl std::future::Future<Output = Result<(), AudioError>> + Send;
    37→
    38→    /// Speak text using TTS
    39→    fn speak(&self, text: &str)
    40→        -> impl std::future::Future<Output = Result<(), AudioError>> + Send;
    41→
    42→    /// Play a tone
    43→    fn play_tone(
    44→        &self,
    45→        frequency_hz: u32,
    46→        duration_ms: u32,
    47→    ) -> impl std::future::Future<Output = Result<(), AudioError>> + Send;
    48→
    49→    /// Set master volume (0-100)
    50→    fn set_volume(&self, volume: u8);
    51→
    52→    /// Get current volume
    53→    fn get_volume(&self) -> u8;
    54→
    55→    /// Queue an audio item
    56→    fn queue(&self, item: AudioItem);
    57→
    58→    /// Check if currently playing
    59→    fn is_playing(&self) -> bool;
    60→
    61→    /// Stop current playback
    62→    fn stop(&self);
    63→
    64→    /// Subscribe to audio events
    65→    fn subscribe_events(&self) -> broadcast::Receiver<AudioEvent>;
    66→}
    67→
    68→/// Queue entry with priority ordering
    69→#[derive(Debug)]
    70→struct QueueEntry {
    71→    item: AudioItem,
    72→    sequence: u64, // For stable ordering within same priority
    73→}
    74→
    75→impl PartialEq for QueueEntry {
    76→    fn eq(&self, other: &Self) -> bool {
    77→        self.item.priority == other.item.priority && self.sequence == other.sequence
    78→    }
    79→}
    80→
    81→impl Eq for QueueEntry {}
    82→
    83→impl PartialOrd for QueueEntry {
    84→    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
    85→        Some(self.cmp(other))
    86→    }
    87→}
    88→
    89→impl Ord for QueueEntry {
    90→    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
    91→        // Higher priority first, then lower sequence (earlier queued)
    92→        // BinaryHeap is a max-heap, so larger items are popped first.
    93→        // We want high priority to come first, so compare priorities directly.
    94→        match self.item.priority.cmp(&other.item.priority) {
    95→            std::cmp::Ordering::Equal => {
    96→                // For same priority, earlier sequence should come first (reverse order)
    97→                other.sequence.cmp(&self.sequence)
    98→            }
    99→            priority_cmp => priority_cmp,
   100→        }
   101→    }
   102→}
   103→
   104→/// Default audio engine implementation
   105→pub struct DefaultAudioEngine {
   106→    config: Arc<Mutex<AudioConfig>>,
   107→    queue: Arc<Mutex<BinaryHeap<QueueEntry>>>,
   108→    sequence_counter: Arc<Mutex<u64>>,
   109→    is_playing: Arc<Mutex<bool>>,
   110→    event_tx: broadcast::Sender<AudioEvent>,
   111→    /// Thread-safe TTS provider for speech synthesis
   112→    tts_provider: Arc<ThreadSafeTtsProvider>,
   113→    /// Priority of the currently playing item (None if not playing)
   114→    current_priority: Arc<Mutex<Option<AudioPriority>>>,
   115→    /// Flag to signal that current playback should be interrupted
   116→    interrupt_requested: Arc<AtomicBool>,
   117→}
   118→
   119→impl DefaultAudioEngine {
   120→    /// Create a new audio engine with the given configuration
   121→    pub fn new(config: AudioConfig) -> Self {
   122→        let (event_tx, _) = broadcast::channel(100);
   123→
   124→        // Create and configure the TTS provider
   125→        let tts_provider = Arc::new(ThreadSafeTtsProvider::new());
   126→
   127→        // Apply configuration settings to TTS provider
   128→        // Convert voice_volume from 0-100 to 0.0-1.0
   129→        let voice_volume = config.voice_volume as f32 / 100.0;
   130→        tts_provider.set_volume(voice_volume);
   131→        tts_provider.set_rate(config.speech_rate);
   132→
   133→        Self {
   134→            config: Arc::new(Mutex::new(config)),
   135→            queue: Arc::new(Mutex::new(BinaryHeap::new())),
   136→            sequence_counter: Arc::new(Mutex::new(0)),
   137→            is_playing: Arc::new(Mutex::new(false)),
   138→            event_tx,
   139→            tts_provider,
   140→            current_priority: Arc::new(Mutex::new(None)),
   141→            interrupt_requested: Arc::new(AtomicBool::new(false)),
   142→        }
   143→    }
   144→
   145→    /// Update TTS settings from the current config
   146→    fn update_tts_settings(&self) {
   147→        let config = self.config.lock().unwrap();
   148→        // Convert voice_volume from 0-100 to 0.0-1.0
   149→        let voice_volume = config.voice_volume as f32 / 100.0;
   150→        self.tts_provider.set_volume(voice_volume);
   151→        self.tts_provider.set_rate(config.speech_rate);
   152→    }
   153→
   154→    /// Get access to the TTS provider for voice enumeration and configuration
   155→    pub fn tts_provider(&self) -> &ThreadSafeTtsProvider {
   156→        &self.tts_provider
   157→    }
   158→
   159→    /// Update audio configuration
   160→    pub fn update_config(&self, config: AudioConfig) {
   161→        let mut current = self.config.lock().unwrap();
   162→        *current = config;
   163→        drop(current);
   164→        self.update_tts_settings();
   165→    }
   166→
   167→    /// Check if a new item's priority should interrupt the current playback
   168→    fn should_interrupt(&self, new_priority: AudioPriority) -> bool {
   169→        let current = self.current_priority.lock().unwrap();
   170→        match *current {
   171→            None => false, // Nothing playing, no need to interrupt
   172→            Some(current_priority) => {
   173→                // High and Critical priority items interrupt lower-priority items
   174→                // Critical interrupts everything except other Critical items
   175→                // High interrupts Normal and Low
   176→                match new_priority {
   177→                    AudioPriority::Critical => current_priority != AudioPriority::Critical,
   178→                    AudioPriority::High => {
   179→                        current_priority == AudioPriority::Normal
   180→                            || current_priority == AudioPriority::Low
   181→                    }
   182→                    _ => false,
   183→                }
   184→            }
   185→        }
   186→    }
   187→
   188→    /// Request interruption of current playback
   189→    fn request_interrupt(&self) {
   190→        self.interrupt_requested.store(true, Ordering::Release);
   191→        // Actually stop the TTS
   192→        self.tts_provider.stop();
   193→    }
   194→
   195→    /// Clear the interrupt flag
   196→    fn clear_interrupt(&self) {
   197→        self.interrupt_requested.store(false, Ordering::Release);
   198→    }
   199→
   200→    /// Check if interruption was requested
   201→    fn is_interrupt_requested(&self) -> bool {
   202→        self.interrupt_requested.load(Ordering::Acquire)
   203→    }
   204→
   205→    /// Clear items from the queue below the given priority
   206→    fn clear_lower_priority(&self, min_priority: AudioPriority) {
   207→        let mut queue = self.queue.lock().unwrap();
   208→        let entries: Vec<QueueEntry> = queue.drain().collect();
   209→
   210→        // Re-add only items with priority >= min_priority
   211→        for entry in entries {
   212→            if entry.item.priority >= min_priority {
   213→                queue.push(entry);
   214→            } else {
   215→                tracing::debug!(
   216→                    "Cleared lower-priority audio item: {:?}",
   217→                    entry.item.audio_type
   218→                );
   219→            }
   220→        }
   221→    }
   222→
   223→    /// Clear all items from the queue
   224→    pub fn clear_queue(&self) {
   225→        let mut queue = self.queue.lock().unwrap();
   226→        queue.clear();
   227→        tracing::debug!("Audio queue cleared");
   228→    }
   229→
   230→    /// Get the highest priority item in the queue without removing it
   231→    fn peek_highest_priority(&self) -> Option<AudioPriority> {
   232→        let queue = self.queue.lock().unwrap();
   233→        queue.peek().map(|entry| entry.item.priority)
   234→    }
   235→
